    const p = pointFor(c.boss, c.state);
    const distance = Math.max(1, dist(c.boss, p));
    c.boss.dashTimer = Math.min(0.6, distance / 500);
    c.boss.dashVx = (p.x - c.boss.x) / distance * 500;
    c.boss.dashVy = (p.y - c.boss.y) / distance * 500;
